package com.example.basic.apk

import android.util.Base64

/**
 * Embedded binary XML vector assets for adaptive icon foregrounds and backgrounds.
 * Guaranteed to be available with zero filesystem or asset stream dependencies.
 */
object RetroIconData {
    private val FG_BASE64 = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    private val BG_BASE64 = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    private fun decodeBase64(str: String): ByteArray {
        return try {
            android.util.Base64.decode(str, android.util.Base64.DEFAULT)
        } catch (_: Throwable) {
            java.util.Base64.getDecoder().decode(str)
        }
    }

    fun getForegroundBytes(index: Int): ByteArray {
        val idx = index.coerceIn(0, 7)
        return decodeBase64(FG_BASE64[idx])
    }

    fun getBackgroundBytes(index: Int): ByteArray {
        val idx = index.coerceIn(0, 7)
        return decodeBase64(BG_BASE64[idx])
    }
}
